SRC = 'gemm.cpp'
EXE = 'gemm'
BUILD = ['g++', '-O2', '-std=c++17', '-Wall', '-Wextra', '-o', 'gemm', 'gemm.cpp']
WARM = '1 1\n'
# The solution runs from a PRIVATE copy, never from the agent-writable
# fixture dir: a compiled unit's binary is built there (start_build), and a
# Python unit's source is copied there and run confined to it.
