def fail(msg):
    print('FAIL: ' + msg)
    sys.exit(1)

# --- library guard -----------------------------------------------------------
# The multiply must be the solution's own code. A vendor BLAS (Accelerate,
# OpenBLAS, MKL, cuBLAS) answers the whole task in one call, and dlopen needs
# no compile or link flag, so the fixed build command alone does not stop it.
# Three layers, each enough for the cheats seen so far:
#   1. a source lint, for a clear message on the plain spellings;
#   2. the built binary: the libraries it links and the symbols it imports
#      (no loader, no BLAS name), however the source spelled them;
#   3. the running process: every image it loads. macOS: a monitor dylib,
#      inserted by the validator, kills the process the moment a library
#      outside the system runtime is added. Linux: the validator reads
#      /proc/<pid>/maps while the solution runs and kills it on a mapping
#      of any other executable file.
import hashlib, re, signal, struct, tempfile, threading

_GDIR = tempfile.mkdtemp(prefix='libguard_', dir=os.getcwd())
_MON = os.path.join(_GDIR, 'mon.dylib')
_ALIVE = os.path.join(_GDIR, 'alive')
_mon_build = None
_mon_hash = None

_LINT = {
    'common': r'dlopen|dlsym|dlmopen|dlvsym|dlfcn|RTLD_|cblas|openblas|vecLib|Accelerate\.framework|'
              r'_dyld|dyld_|shared_cache|NSAddImage|LD_PRELOAD|LD_AUDIT|DYLD_|link_map|r_debug|__RESTRICT',
    'c': r'#\s*pragma\s+comment|__asm__\s*\(\s*"\s*\.(?:incbin|section)',
    'cpp': r'#\s*pragma\s+comment|__asm__\s*\(\s*"\s*\.(?:incbin|section)',
    'go': r'import\s+"C"|#cgo|go:cgo_|go:linkname|"plugin"|purego|"syscall"|golang\.org/x/sys',
    'rust': r'\bextern\s*"|#\s*!?\[\s*link\b|link\s*\(\s*name|link_section|link_name|\bextern\s+crate',
    'zig': r'\bextern\b|DynLib|@cImport|linkSystemLibrary|linksection|callconv\s*\(\s*\.c\s*\)',
}
_BAD_IMPORT = re.compile(r'(?i)dlopen|dlmopen|dlsym|dlvsym|dl_open|NSAddImage|NSAddLibrary|NSLinkModule|'
                         r'NSCreateObjectFile|NSLookup|shared_cache|gemm|blas|lapack|vdsp|bnns|catlas|'
                         r'cuda|mkl_|lazy_load')
_BAD_DEFINED = re.compile(r'DynLib|dlopen|_dl_open|dl_map_object')
_DARWIN_LIBS = {'/usr/lib/libSystem.B.dylib', '/usr/lib/libc++.1.dylib',
                '/usr/lib/libc++abi.dylib', '/usr/lib/libresolv.9.dylib'}
_LINUX_LIB = re.compile(r'^(?:libc|libm|libpthread|libdl|librt|libutil|libgcc_s|libstdc\+\+|libc\+\+|'
                        r'libc\+\+abi|libunwind|libresolv|ld-linux[-\w]*|ld-musl[-\w]*)'
                        r'(?:-[\d.]+)?\.so(?:\.\d+)*$')
_LINUX_DIRS = ('/lib/', '/lib64/', '/usr/lib/', '/usr/lib64/')

_MON_SRC = r'''
#include <dlfcn.h>
#include <fcntl.h>
#include <mach-o/dyld.h>
#include <mach-o/loader.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
static const struct mach_header *self_mh, *main_mh;
static const char *ok[] = {"/usr/lib/libSystem.B.dylib", "/usr/lib/libc++.1.dylib",
    "/usr/lib/libc++abi.dylib", "/usr/lib/libobjc.A.dylib", "/usr/lib/libRosetta.dylib",
    "/usr/lib/libresolv.9.dylib", 0};
static void bad(const char *p) {
    static const char m[] = "OPENBEAST_LIBGUARD: loaded ";
    write(2, m, sizeof m - 1); write(2, p, strlen(p)); write(2, "\n", 1);
    _exit(86);
}
static void cb(const struct mach_header *mh, intptr_t slide) {
    (void)slide;
    if (mh == self_mh || mh == main_mh) return;
    Dl_info i;
    if (!dladdr(mh, &i) || !i.dli_fname) bad("(unnamed image)");
    if (strncmp(i.dli_fname, "/usr/lib/system/", 16) == 0) return;
    for (int k = 0; ok[k]; k++) if (strcmp(i.dli_fname, ok[k]) == 0) return;
    bad(i.dli_fname);
}
static int anchor;
__attribute__((constructor)) static void init(void) {
    Dl_info i;
    if (dladdr(&anchor, &i)) self_mh = (const struct mach_header *)i.dli_fbase;
    for (uint32_t k = 0; k < _dyld_image_count(); k++) {
        const struct mach_header *h = _dyld_get_image_header(k);
        if (h && h->filetype == MH_EXECUTE) { main_mh = h; break; }
    }
    if (!main_mh) bad("(no main executable)");
    _dyld_register_func_for_add_image(cb);
    const char *a = getenv("OPENBEAST_LIBGUARD_ALIVE");
    if (a) { int fd = open(a, O_WRONLY | O_CREAT | O_TRUNC, 0600); if (fd >= 0) { write(fd, "1", 1); close(fd); } }
    unsetenv("OPENBEAST_LIBGUARD_ALIVE");
    unsetenv("DYLD_INSERT_LIBRARIES");
}
'''


# Comment and literal tokens per language, for the lint's code view.
_STR = r'"(?:\\.|[^"\\\n])*"'
_CHR = r"'(?:\\.|[^'\\\n])*'"
_TOK = {
    'c': _STR + '|' + _CHR + r'|//[^\n]*|/\*.*?\*/',
    'cpp': _STR + '|' + _CHR + r'|//[^\n]*|/\*.*?\*/',
    'go': r'`[^`]*`|' + _STR + '|' + _CHR + r'|//[^\n]*|/\*.*?\*/',
    # a Rust char literal is one (escaped) char: 'a in a lifetime is not one
    'rust': r'"(?:\\.|[^"\\])*"|' + r"'(?:\\[^'\n]{1,10}|[^'\\\n])'" + r'|//[^\n]*|/\*.*?\*/',
    'zig': _STR + '|' + _CHR + r'|\\\\[^\n]*|//[^\n]*',
}


def _code_view(src, keep_strings):
    """src with every comment blanked and, unless keep_strings, every string
    and char literal emptied (its quotes kept)."""
    def sub(m):
        t = m.group(0)
        if t.startswith('//') and LANG == 'go' and re.match(r'//go:|//\s*#cgo', t):
            return t
        if t.startswith(('//', '/*')):
            return ' '
        if keep_strings:
            return t
        return t[0] + t[-1] if t[0] in '"\'`' else ' '
    return re.sub(_TOK[LANG], sub, src, flags=re.S)


def guard_start():
    """Lint the source and, on macOS, start compiling the monitor."""
    global _mon_build
    with open(os.path.join(D, SRC), encoding='utf-8', errors='replace') as f:
        src = f.read().replace('\\\n', '')
    # The lint reads code, not prose: `// no BLAS, no dlopen` failed a correct
    # 122_c (G24). Comments never count; the common words are matched with
    # string and char literal contents blanked too (the binary and runtime
    # checks below see through any spelling), the language rules on code
    # with its strings kept (import "syscall", extern "C", asm(".incbin")).
    # Go's //go: and #cgo directives are comments that act, so they stay.
    for key, text in (('common', _code_view(src, False)), (LANG, _code_view(src, True))):
        m = re.search(_LINT[key], text)
        if m:
            fail('the multiply must be your own code: %s may not use %r (no BLAS, no '
                 'dynamic loading, no foreign linkage)' % (SRC, m.group(0)))
    if sys.platform == 'darwin':
        with open(os.path.join(_GDIR, 'mon.c'), 'w') as f:
            f.write(_MON_SRC)
        # the pinned clang: a planted one could build a no-op monitor
        _mon_build = subprocess.Popen([vlib.tool_path('clang'), '-O2', '-dynamiclib',
                                       '-o', _MON, 'mon.c'],
                                      cwd=_GDIR, env=vlib.build_env(), stdin=subprocess.DEVNULL,
                                      stdout=subprocess.PIPE, stderr=subprocess.STDOUT,
                                      start_new_session=True)


def _tool(argv):
    try:
        # otool / nm by the path the harness pinned (a planted `nm` that
        # prints nothing would empty this layer), under a clean env.
        r = subprocess.run([vlib.tool_path(argv[0])] + list(argv[1:]),
                           capture_output=True, text=True, timeout=vlib.t(20),
                           env=vlib.build_env(), stdin=subprocess.DEVNULL)
    except (OSError, subprocess.TimeoutExpired) as e:
        fail('library check could not run %s: %s' % (argv[0], e))
    if r.returncode != 0:
        fail('library check: %s failed: %s' % (argv[0], (r.stderr or r.stdout)[-300:]))
    return r.stdout


def _elf(path):
    """(needed, undefined dynamic symbols, defined symbols, is_dynamic) of an ELF64 LE file."""
    with open(path, 'rb') as f:
        b = f.read()
    if b[:4] != b'\x7fELF' or b[4] != 2 or b[5] != 1:
        fail('library check: the binary is not a 64-bit little-endian ELF file')
    phoff, shoff = struct.unpack_from('<QQ', b, 0x20)
    phentsize, phnum, shentsize, shnum = struct.unpack_from('<HHHH', b, 0x36)
    dynamic = False
    for k in range(phnum):
        if struct.unpack_from('<I', b, phoff + k * phentsize)[0] in (2, 3):  # PT_DYNAMIC, PT_INTERP
            dynamic = True
    secs = [struct.unpack_from('<IIQQQQIIQQ', b, shoff + k * shentsize) for k in range(shnum)]
    if dynamic and not any(s[1] == 11 for s in secs):
        fail('library check: dynamic binary without a .dynsym section')

    def cstr(off):
        return b[off:b.index(b'\0', off)].decode('latin-1')

    needed, undef, defined = [], [], []
    for s in secs:
        typ, off, size, link, entsize = s[1], s[4], s[5], s[6], s[9]
        if typ in (2, 11):  # SYMTAB, DYNSYM
            stroff = secs[link][4]
            for e in range(0, size, entsize or 24):
                name, info, other, shndx = struct.unpack_from('<IBBH', b, off + e)
                if not name:
                    continue
                nm = cstr(stroff + name)
                (undef if shndx == 0 else defined).append(nm)
        elif typ == 6:  # DYNAMIC
            stroff = secs[link][4]
            for e in range(0, size, 16):
                tag, val = struct.unpack_from('<qQ', b, off + e)
                if tag == 0:
                    break
                if tag == 1:  # DT_NEEDED
                    needed.append(cstr(stroff + val))
    return needed, undef, defined, dynamic


def guard_binary():
    """The built binary links only the system runtime and imports no loader."""
    exe = RUN[0]
    if sys.platform == 'darwin':
        libs = [l.strip().split(' (')[0] for l in _tool(['otool', '-L', exe]).splitlines()[1:] if l.strip()]
        undef = _tool(['nm', '-u', exe]).split()
        defined = [l.split()[-1] for l in _tool(['nm', '-U', exe]).splitlines() if l.split()]
        if re.search(r'segname\s+__RESTRICT|sectname\s+__restrict', _tool(['otool', '-l', exe])):
            fail('the binary may not carry a __RESTRICT segment')
        for lib in libs:
            if lib not in _DARWIN_LIBS:
                fail('the binary may link only the system runtime, not %s' % lib)
    else:
        needed, undef, defined, _ = _elf(exe)
        for lib in needed:
            if not _LINUX_LIB.match(lib):
                fail('the binary may link only the system runtime, not %s' % lib)
    for sym in undef:
        if _BAD_IMPORT.search(sym):
            fail('the multiply must be your own code: the binary imports %s' % sym)
    for sym in defined:
        if _BAD_DEFINED.search(sym):
            fail('the multiply must be your own code: the binary contains a loader (%s)' % sym)


def guard_monitor_ready():
    global _mon_hash
    if _mon_build is None:
        return
    out, _ = _mon_build.communicate(timeout=vlib.t(25))
    if _mon_build.returncode != 0:
        fail('library monitor did not build: ' + out.decode('utf-8', 'replace')[-300:])
    with open(_MON, 'rb') as f:
        _mon_hash = hashlib.sha256(f.read()).hexdigest()


class _MapWatch:
    """Linux: poll the solution's memory maps for executable files outside the
    system runtime, and kill the process group on the first one."""

    def __init__(self, exe):
        self.exe = os.path.realpath(exe)
        self.bad = None
        self.stop = threading.Event()
        self.th = threading.Thread(target=self.loop, daemon=True)
        self.th.start()

    def children(self):
        out = set()
        try:
            for tid in os.listdir('/proc/self/task'):
                try:
                    with open('/proc/self/task/%s/children' % tid) as f:
                        out.update(int(p) for p in f.read().split())
                except OSError:
                    pass
        except OSError:
            pass
        return out

    def allowed(self, path):
        if path == self.exe:
            return True
        return path.startswith(_LINUX_DIRS) and bool(_LINUX_LIB.match(os.path.basename(path)))

    def check(self, pid):
        try:
            with open('/proc/%d/maps' % pid) as f:
                lines = f.read().splitlines()
        except OSError:
            return
        for line in lines:
            parts = line.split(None, 5)
            if len(parts) < 6 or not parts[5].startswith('/'):
                continue
            path = parts[5]
            if path.endswith(' (deleted)'):
                path = path[:-10]
            if ('x' in parts[1] or _BAD_IMPORT.search(os.path.basename(path))) and not self.allowed(path):
                self.bad = path
                try:
                    os.killpg(pid, signal.SIGKILL)
                except OSError:
                    pass
                return

    def loop(self):
        while not self.stop.is_set() and self.bad is None:
            for pid in self.children():
                self.check(pid)
            self.stop.wait(0.003)

    def finish(self):
        self.stop.set()
        self.th.join()
        return self.bad


def guarded(cmd, **kw):
    """vlib.run_solution with the runtime library guard around it."""
    if sys.platform == 'darwin':
        with open(_MON, 'rb') as f:
            if hashlib.sha256(f.read()).hexdigest() != _mon_hash:
                fail('library monitor was modified')
        if os.path.exists(_ALIVE):
            os.remove(_ALIVE)
        # sandbox-exec is SIP-protected, so DYLD_* in the environment would be
        # dropped on its exec; /usr/bin/env sets it after that, for the solution.
        r = vlib.run_solution(['/usr/bin/env', 'DYLD_INSERT_LIBRARIES=' + _MON,
                               'OPENBEAST_LIBGUARD_ALIVE=' + _ALIVE] + list(cmd), **kw)
        if 'OPENBEAST_LIBGUARD' in (r.stderr or '') or r.returncode == 86:
            fail('the multiply must be your own code: the solution loaded a library outside '
                 'the system runtime')
        if r.verdict == 'ok' and not os.path.exists(_ALIVE):
            fail('library monitor did not load into the solution')
        return r
    w = _MapWatch(cmd[0]) if sys.platform.startswith('linux') else None
    r = vlib.run_solution(cmd, **kw)
    if w is not None:
        bad = w.finish()
        if bad:
            fail('the multiply must be your own code: the solution mapped %s' % bad)
    return r


if not os.path.isfile(os.path.join(D, SRC)):
    fail(SRC + ' not found in ' + D)
_build = None


def start_build():
    # Review 1116: the compile used to run in the fixture dir with the
    # compiler found on PATH, so a `gcc` (or a go.mod + go env + `go1.99`)
    # planted by the agent compiled the REFERENCE and an empty main passed.
    # Now: a private copy of only the source, the compiler the harness pinned
    # before the agent ran, a clean env, and a native executable required.
    global _build, WORK, RUN, CONFINE
    with open(os.path.join(D, SRC), 'rb') as f:
        source = f.read()
    if BUILD is None:
        WORK = vlib.private_build_dir({SRC: source})
        RUN = vlib.python_cmd(os.path.join(WORK, SRC))
        # Reads only the interpreter's stdlib (no site-packages, no repo, no
        # stray copy of a reference) and its own dir, on macOS and Linux.
        CONFINE = {'confine': [WORK],
                   'read_only': vlib.python_runtime(sys.executable, PY_MODULES)}
        return
    _build = vlib.start_build({SRC: source}, BUILD, EXE, extra_env=BUILD_ENV)
    WORK = _build.dir
    RUN = [_build.product]


def finish_build():
    if _build is None:
        return
    ok, out = _build.finish(vlib.t(25))
    if ok is None:
        fail('compile timed out')
    if not ok:
        fail('compile failed: ' + out[-400:])
    # Untimed first exec: macOS scans a fresh binary on its first run, which
    # costs seconds of wall time that say nothing about the code.
    guard_binary()
    guard_monitor_ready()
    guarded(RUN, input=WARM, cpu_s=5, wall_s=20, cwd=WORK)


# The solution runs in its own session under vlib.run_solution: the CPU
# budget counts the whole process tree (every thread and every descendant),
# and any child process, orphaned or not, is refused. Wall time is only a
# backstop for a solution that sleeps or blocks.
def run(inp, cpu, wall, fixed_cpu=False):
    r = guarded(RUN, input=inp, cpu_s=cpu, wall_s=wall, cwd=WORK,
                scale_cpu=not fixed_cpu)
    if r.verdict == 'cpu':
        fail('solution timed out (CPU limit %gs)' % (cpu if fixed_cpu else vlib.t(cpu)))
    if r.verdict == 'wall':
        fail('solution timed out (wall limit %gs)' % vlib.t(wall))
    if r.verdict in ('forked', 'daemon'):
        fail('solution must not start other processes (%s)' % r.reason)
    if r.verdict != 'ok':
        fail('solution refused: ' + r.reason)
    if r.returncode != 0:
        fail('solution exited with status %d' % r.returncode)
    return r.stdout


def numbers(text, want, case):
    toks = text.split()
    if len(toks) != want:
        fail('case %d: expected %d output values, got %d' % (case, want, len(toks)))
    try:
        return [float(t) for t in toks]
    except ValueError:
        fail('case %d: unparseable output value' % case)

from operator import mul
GP = 2147483647
GG = 48271


def gm_seq(seed, start, count):
    x = seed * pow(GG, start, GP) % GP
    out = [0] * count
    for t in range(count):
        x = x * GG % GP
        out[t] = x
    return out


_gm_cols = {}


def gm_rows(n, seed, rows):
    cols = _gm_cols.get((n, seed))
    if cols is None:
        # Transpose in the integer domain, so each column's floats are
        # allocated together. Slicing a row-major float list left every
        # column a list of pointers 2048 slots apart: on GB10 (aarch64) the
        # 18 x 2048 dot products chased them through ~100 MB, 6.8 s of the
        # validation (review 1116); this is 3.1 s, and bit-identical (same
        # values, same summation order).
        bi = gm_seq(seed, n * n, n * n)
        cols = _gm_cols[(n, seed)] = [[v / GP for v in bi[j::n]] for j in range(n)]
    res = {}
    for i in rows:
        a = [v / GP for v in gm_seq(seed, i * n, n)]
        c = [sum(map(mul, a, col)) for col in cols]
        res[i] = (sum(v * v for v in c), max(c))
    return res

# CPU is the measured quantity, so its budget does not scale with the
# harness's contention multiplier; the wall backstop does.
CPU, WALL = 12, 20
rng = random.Random(0x6E33)
seed = lambda: rng.randrange(1, GP)
small = [(1, seed()), (2, seed()), (17, seed()), (100, seed()), (257, seed())]
# The big case is fresh on every run, seed and checked rows both: nothing a
# solution saw in an earlier run (or could cache from one) says which matrix
# it will be asked for or which of its rows will be read.
sysrng = random.SystemRandom()
big_n = 2048
big = (big_n, sysrng.randrange(1, GP))
big_rows = sorted({0, big_n - 1} | set(sysrng.sample(range(1, big_n - 1), 16)))
guard_start()
start_build()
want = [gm_rows(n, s, range(n)) for n, s in small]
want_big = gm_rows(big[0], big[1], big_rows)
finish_build()


def check(case, n, got_text, rows):
    got = numbers(got_text, 2 * n, case)
    # Every row, cheaply: A and B are positive, so 0 < C[i][j] < n, and
    # M_i^2 <= S_i <= n * M_i^2 for every line, not only the sampled ones.
    for i in range(n):
        S, M = got[2 * i], got[2 * i + 1]
        if not (0.0 < M < n and M * M * (1 - 1e-9) <= S <= n * M * M * (1 + 1e-9)):
            fail('mismatch at case %d' % case)
    for i, (S, M) in rows.items():
        for g, w in ((got[2 * i], S), (got[2 * i + 1], M)):
            if not abs(g - w) <= 1e-9 * abs(w) + 1e-12:
                fail('mismatch at case %d' % case)


for c, ((n, s), w) in enumerate(zip(small, want)):
    check(c, n, run('%d %d\n' % (n, s), CPU, WALL, fixed_cpu=True), w)
check(len(small), big[0], run('%d %d\n' % big, CPU, WALL, fixed_cpu=True), want_big)
print('OK: %d hidden cases' % (len(small) + 1))

import os, subprocess, sys, random, math
import vlib
D = '/tmp/eval_gemm'
SRC = 'gemm.rs'
EXE = 'gemm'
BUILD = ['rustc', '-O', '--edition', '2021', 'gemm.rs', '-o', 'gemm']
WARM = '1 1\n'
# The solution runs from a PRIVATE copy, never from the agent-writable
# fixture dir: a compiled unit's binary is built there (start_build), and a
# Python unit's source is copied there and run confined to it.
WORK = None
RUN = None
CONFINE = {}
PY_MODULES = ('math', 'cmath', 'sys', 'os', 'io', 're', 'decimal', 'fractions', 'statistics', 'functools', 'itertools', 'operator', 'collections', 'array', 'struct', 'bisect', 'heapq', 'random', 'time')
LANG = 'rust'
BUILD_ENV = None


def fail(msg):
    print('FAIL: ' + msg)
    sys.exit(1)

# --- library guard -----------------------------------------------------------
# The multiply must be the solution's own code. A vendor BLAS (Accelerate,
# OpenBLAS, MKL, cuBLAS) answers the whole task in one call, and dlopen needs
# no compile or link flag, so the fixed build command alone does not stop it.
# Three layers, each enough for the cheats seen so far:
#   1. a source lint, for a clear message on the plain spellings;
#   2. the built binary: the libraries it links and the symbols it imports
#      (no loader, no BLAS name), however the source spelled them;
#   3. the running process: every image it loads. macOS: a monitor dylib,
#      inserted by the validator, kills the process the moment a library
#      outside the system runtime is added. Linux: the validator reads
#      /proc/<pid>/maps while the solution runs and kills it on a mapping
#      of any other executable file.
import hashlib, re, signal, struct, tempfile, threading

_GDIR = tempfile.mkdtemp(prefix='libguard_', dir=os.getcwd())
_MON = os.path.join(_GDIR, 'mon.dylib')
_ALIVE = os.path.join(_GDIR, 'alive')
_mon_build = None
_mon_hash = None

_LINT = {
    'common': r'dlopen|dlsym|dlmopen|dlvsym|dlfcn|RTLD_|cblas|openblas|vecLib|Accelerate\.framework|'
              r'_dyld|dyld_|shared_cache|NSAddImage|LD_PRELOAD|LD_AUDIT|DYLD_|link_map|r_debug|__RESTRICT',
    'c': r'#\s*pragma\s+comment|__asm__\s*\(\s*"\s*\.(?:incbin|section)',
    'cpp': r'#\s*pragma\s+comment|__asm__\s*\(\s*"\s*\.(?:incbin|section)',
    'go': r'import\s+"C"|#cgo|go:cgo_|go:linkname|"plugin"|purego|"syscall"|golang\.org/x/sys',
    'rust': r'\bextern\s*"|#\s*!?\[\s*link\b|link\s*\(\s*name|link_section|link_name|\bextern\s+crate',
    'zig': r'\bextern\b|DynLib|@cImport|linkSystemLibrary|linksection|callconv\s*\(\s*\.c\s*\)',
}
_BAD_IMPORT = re.compile(r'(?i)dlopen|dlmopen|dlsym|dlvsym|dl_open|NSAddImage|NSAddLibrary|NSLinkModule|'
                         r'NSCreateObjectFile|NSLookup|shared_cache|gemm|blas|lapack|vdsp|bnns|catlas|'
                         r'cuda|mkl_|lazy_load')
_BAD_DEFINED = re.compile(r'DynLib|dlopen|_dl_open|dl_map_object')
_DARWIN_LIBS = {'/usr/lib/libSystem.B.dylib', '/usr/lib/libc++.1.dylib',
                '/usr/lib/libc++abi.dylib', '/usr/lib/libresolv.9.dylib'}
_LINUX_LIB = re.compile(r'^(?:libc|libm|libpthread|libdl|librt|libutil|libgcc_s|libstdc\+\+|libc\+\+|'
                        r'libc\+\+abi|libunwind|libresolv|ld-linux[-\w]*|ld-musl[-\w]*)'
                        r'(?:-[\d.]+)?\.so(?:\.\d+)*$')
_LINUX_DIRS = ('/lib/', '/lib64/', '/usr/lib/', '/usr/lib64/')

_MON_SRC = r'''
#include <dlfcn.h>
#include <fcntl.h>
#include <mach-o/dyld.h>
#include <mach-o/loader.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
static const struct mach_header *self_mh, *main_mh;
static const char *ok[] = {"/usr/lib/libSystem.B.dylib", "/usr/lib/libc++.1.dylib",
    "/usr/lib/libc++abi.dylib", "/usr/lib/libobjc.A.dylib", "/usr/lib/libRosetta.dylib",
    "/usr/lib/libresolv.9.dylib", 0};
static void bad(const char *p) {
    static const char m[] = "OPENBEAST_LIBGUARD: loaded ";
    write(2, m, sizeof m - 1); write(2, p, strlen(p)); write(2, "\n", 1);
    _exit(86);
}
static void cb(const struct mach_header *mh, intptr_t slide) {
    (void)slide;
    if (mh == self_mh || mh == main_mh) return;
    Dl_info i;
    if (!dladdr(mh, &i) || !i.dli_fname) bad("(unnamed image)");
    if (strncmp(i.dli_fname, "/usr/lib/system/", 16) == 0) return;
    for (int k = 0; ok[k]; k++) if (strcmp(i.dli_fname, ok[k]) == 0) return;
    bad(i.dli_fname);
}
static int anchor;
__attribute__((constructor)) static void init(void) {
    Dl_info i;
    if (dladdr(&anchor, &i)) self_mh = (const struct mach_header *)i.dli_fbase;
    for (uint32_t k = 0; k < _dyld_image_count(); k++) {
        const struct mach_header *h = _dyld_get_image_header(k);
        if (h && h->filetype == MH_EXECUTE) { main_mh = h; break; }
    }
    if (!main_mh) bad("(no main executable)");
    _dyld_register_func_for_add_image(cb);
    const char *a = getenv("OPENBEAST_LIBGUARD_ALIVE");
    if (a) { int fd = open(a, O_WRONLY | O_CREAT | O_TRUNC, 0600); if (fd >= 0) { write(fd, "1", 1); close(fd); } }
    unsetenv("OPENBEAST_LIBGUARD_ALIVE");
    unsetenv("DYLD_INSERT_LIBRARIES");
